# filename: parse_house_positions.py

def parse_house_positions(fp):
    with open(fp, 'r') as f:
        lines = [line.rstrip('\n') for line in f]
    # find the first line that looks like the road (contains '-' and no letters)
    road_idx = None
    for i, line in enumerate(lines):
        if '-' in line and all(c in '- ' for c in line):
            road_idx = i
            break
    if road_idx is None:
        raise ValueError('Road line not found')
    house_positions = set()
    for off in (-1, 1):
        j = road_idx + off
        if 0 <= j < len(lines):
            for pos, ch in enumerate(lines[j]):
                if ch == 'H':
                    house_positions.add(pos)
    return sorted(house_positions)

